import "./Nav.css";

function Nav(value) {

  return (
    <div className="mainNav">
      <form className="form" onSubmit={(e)=>value(e)}>
        <input type="text" className="text" name="city" />
        <input type="submit" value="Search City" className="search" />
        <div className="radio">
          <input type="radio" id="F" name="temperature" />
          <label htmlFor="F" className="f">
            °F
          </label>
          <input type="radio" id="C" name="temperature" />
          <label htmlFor="C">°C</label>
        </div>
      </form>
    </div>
  );
}

export default Nav;
